import{_ as e}from"./chunks/100.I7A0VXqr.js";import{_ as o,o as a,c as r,ak as i}from"./chunks/framework.DC-k2h36.js";const n="/projects/esp32Sensor/en/latest/assets/1.Dm7EPxDy.webp",l="/projects/esp32Sensor/en/latest/assets/2.DUJg38Jp.webp",s="/projects/esp32Sensor/en/latest/assets/3.DQkrFTfa.webp",c="/projects/esp32Sensor/en/latest/assets/4.Qx51F2VG.webp",y=JSON.parse('{"title":"16. RGB Light Module","description":"","frontmatter":{},"headers":[],"relativePath":"docs/16. RGB Light Module.md","filePath":"docs/16. RGB Light Module.md"}'),d={name:"docs/16. RGB Light Module.md"};function h(g,t,p,m,u,_){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="_16-rgb-light-module" tabindex="-1">16. RGB Light Module <a class="header-anchor" href="#_16-rgb-light-module" aria-label="Permalink to &quot;16. RGB Light Module&quot;">​</a></h1><h2 id="_16-1-introduction" tabindex="-1">16.1 Introduction <a class="header-anchor" href="#_16-1-introduction" aria-label="Permalink to &quot;16.1 Introduction&quot;">​</a></h2><p>The RGB light module is a versatile lighting component. With simple programming, it can stay solidly lit, blink, or create colorful rainbow transitions.</p><img loading="lazy" height="1156" width="1156" src="'+n+'" class="common_img" style="width:300px;"><h2 id="_16-2-technical-specifications" tabindex="-1">16.2 Technical Specifications <a class="header-anchor" href="#_16-2-technical-specifications" aria-label="Permalink to &quot;16.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Color channels</td><td style="text-align:center;">Red, green, blue</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">39.5 × 23.4 × 23.0 mm</td></tr></tbody></table><h2 id="_16-3-hands-on-project" tabindex="-1">16.3 Hands-On Project <a class="header-anchor" href="#_16-3-hands-on-project" aria-label="Permalink to &quot;16.3 Hands-On Project&quot;">​</a></h2><h3 id="_16-3-1-project-overview" tabindex="-1">16.3.1 Project Overview <a class="header-anchor" href="#_16-3-1-project-overview" aria-label="Permalink to &quot;16.3.1 Project Overview&quot;">​</a></h3><p>This project programs the RGB light module to cycle through red, green, and blue before turning off. Each color stays lit for 2 s, demonstrating how to configure colors and control lighting sequences in code.</p><h3 id="_16-3-2-hardware-wiring" tabindex="-1">16.3.2 Hardware Wiring <a class="header-anchor" href="#_16-3-2-hardware-wiring" aria-label="Permalink to &quot;16.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the RGB light module to port <strong>P5</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="588" width="622" src="'+l+'" class="common_img" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This module supports connection to any port among P5, P6, P7, or P8 on the controller. Ensure that the port configured in the program matches the physical wiring.</strong></p></div><h3 id="_16-3-3-adding-extensions" tabindex="-1">16.3.3 Adding Extensions <a class="header-anchor" href="#_16-3-3-adding-extensions" aria-label="Permalink to &quot;16.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>RGB module</strong> under the <strong>Output module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+s+'" class="common_img" style="width:800px;"><h3 id="_16-3-4-complete-program-and-analysis" tabindex="-1">16.3.4 Complete Program and Analysis <a class="header-anchor" href="#_16-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;16.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the main program loop, RGB color configurations and delay routines execute sequentially:</p><ul><li><p>Set the RGB light on port P5 to red, then wait 2 s.</p></li><li><p>Set the RGB light on port P5 to green with red at 0, green at 255, and blue at 0, then wait 2 s.</p></li><li><p>Set the RGB light on port P5 to blue, then wait 2 s.</p></li><li><p>Turn off the RGB light on port P5, then wait 2 s.</p></li></ul></li><li><p>The program repeats this entire RGB color-switching sequence continuously in a loop.</p></li></ol><img loading="lazy" height="495" width="592" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1TXgifpt9LbPfn2A8MxY_fA1Vpq4xoemE?usp=sharing" target="_blank" rel="noreferrer">Program Files/16 RGB Light Module.sb3</a>.</strong></p></div><h3 id="_16-3-5-program-upload" tabindex="-1">16.3.5 Program Upload <a class="header-anchor" href="#_16-3-5-program-upload" aria-label="Permalink to &quot;16.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_16-3-6-program-outcome" tabindex="-1">16.3.6 Program Outcome <a class="header-anchor" href="#_16-3-6-program-outcome" aria-label="Permalink to &quot;16.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, the RGB light module cycles through its colors continuously. It lights up in red, green, and blue in order before turning off. Each state lasts for 2 s, clearly showing the transition between different RGB colors.</p>',25)])])}const x=o(d,[["render",h]]);export{y as __pageData,x as default};
